package com.example.bikerental; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity @Table(name="verification_requests") public class VerificationRequest { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String username; @Column(nullable=false) private String documentType; @Column(length=4) private String lastFour; @Column(nullable=false) private String status="PENDING"; private LocalDateTime submittedAt=LocalDateTime.now(); @Column(length=500) private String adminNote; public VerificationRequest(){} public VerificationRequest(String u,String t,String l){username=u;documentType=t;lastFour=l;status="PENDING";} public Long getId(){return id;} public String getUsername(){return username;} public String getDocumentType(){return documentType;} public String getLastFour(){return lastFour;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDateTime getSubmittedAt(){return submittedAt;} public String getAdminNote(){return adminNote;} public void setAdminNote(String v){adminNote=v;} }